codeExample:
// --- CONCEPTUAL UNDERSTANDING ---

// 1. The Browser downloads this HTML string:
// "<html><body><p>Hello</p></body></html>"

// 2. The Browser converts it into the DOM Tree in C++ memory:
/*
   Document
      |
     HTML
      |
     Body
      |
    Paragraph
      |
   "Hello" (TextNode)
*/

// 3. The Browser downloads this CSS string:
// "p { color: red; }"

// 4. The Browser converts it into the CSSOM Tree:
/*
   Paragraph Node -> Rule: color: red;
*/

console.log("JavaScript can manipulate BOTH trees. It manipulates the DOM via document.createElement(), and the CSSOM via element.style.color = 'red'.");
